"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[15128],{96944:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"AimPoseController","desc":"Bends every visible player\'s waist so the held tool points at that player\'s\\naim point (`AimPose`). Aim tools = any `WeaponConfig` Tool (guns along the\\nbarrel; throwables from the Handle along the chest) and the Grabhook.\\n- Local player: the crosshair point (screen-centre ray, as `GunHandler` aims),\\n  sent as `ReqAimPoint` at `AimPoseConfig.ReportHz` while a gun is held.\\n- Other players: the last relayed `AimPointSync` point; older than\\n  `StaleTime` = straight.\\nDead = plain animation. A Fire (throw) or Reload track plays on top of the held pose.\\nRuns on `Stepped` (after the animation step), so the walk sway is cancelled in the same frame.","realm":["Client"],"source":{"line":16,"path":"src/StarterPlayer/StarterPlayerScripts/AimPoseController.client.luau"}}')}}]);